{
    try {
        $f();
    } catch (Throwable $e) {
        return get_class($e);
    }
    return "";
}

function gagalDengan(callable $f): string
{
    try {
        $f();
    } catch (Throwable $e) {
        return get_class($e) . ": " . $e->getMessage();
    }
    return "";
}

