// Pengganti PDO untuk latihan: menyimpan tabel produk di array.
class PernyataanPalsu
{
    private array $hasil = [];

    public function __construct(private DbPalsu $db, public string $sql) {}

    public function execute(array $params = []): bool
    {
        $this->db->log[] = [$this->sql, $params];
        $this->hasil = $this->db->jalankan($this->sql, array_values($params));
        return true;
    }

    public function fetch(): array|false
    {
        return array_shift($this->hasil) ?? false;
    }

    public function fetchAll(): array
    {
        $semua = $this->hasil;
        $this->hasil = [];
        return $semua;
    }
}

class DbPalsu
{
    public array $log = [];
    public array $produk = [];
    private int $id = 0;

    public function prepare(string $sql): PernyataanPalsu
    {
        return new PernyataanPalsu($this, $sql);
    }

    public function lastInsertId(): string
    {
        return (string) $this->id;
    }

    public function jalankan(string $sql, array $p): array
    {
        $sql = trim(preg_replace('/\s+/', ' ', $sql));
        if (preg_match('/^INSERT INTO produk \(nama, harga\) VALUES \((\?, \?|:nama, :harga)\)$/', $sql)) {
            $this->id++;
            $this->produk[$this->id] = ["id" => $this->id, "nama" => $p[0], "harga" => $p[1]];
            return [];
        }
        if (preg_match('/^SELECT \* FROM produk WHERE id = (\?|:id)$/', $sql)) {
            $baris = $this->produk[(int) $p[0]] ?? null;
            return $baris ? [$baris] : [];
        }
        if ($sql === "SELECT * FROM produk ORDER BY id") {
            return array_values($this->produk);
        }
        throw new Exception("SQL tidak dikenali DbPalsu: $sql");
    }
}
